head.script:
///////// 1. 변수 및 선언 영역 /////////

// 이 화면의 역할→버튼id 매핑 — 버튼 id 는 화면마다 달라도 된다(비통일 요건).
// print 는 표준 6역할 외 동적 추가 역할 : 목록형 상태에서는 자동 비활성, "*" 상태(update/enabled)에서는 자동 활성.
// ("new"/"delete" 는 예약어라 따옴표 표기)
scwin.BTN_MAP = {
    "new"    : "btn_add",       // [신규]
    save     : "btnSv01",       // [저장]
    modify   : "btn_edit",      // [수정]
    "delete" : "btnRemove",     // [삭제]
    guide    : "btn_notice2",   // [안내문]
    draft    : "btnGian",       // [기안]
    print    : "btn_prt"        // [출력] — 동적 역할
};

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 26
 * @description 페이지 로드. 화면 전용 상태(printReady)를 등록하고 초기 상태(insertReady)를 적용한다.
 * @hidden N
*/
scwin.onpageload = function () {
    // 진입점 표준 오류 처리 — code-convention §오류 처리
    try {
        // 화면/프로젝트 전용 상태 등록 — 출력·신규만 활성
        $c.util.registerButtonState("printReady", { enable: ["new", "print"] });

        scwin.applyState("insertReady");   // 초기 상태
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.onpageload" });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

// ── 상태 적용 버튼 (thin — 상태값만 넘긴다) ──
scwin.btn_stInsert_onclick      = function () {
    try {
     scwin.applyState("insert"); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_stInsert_onclick" });
    }
};
scwin.btn_stUpdate_onclick      = function () {
    try {
     scwin.applyState("update"); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_stUpdate_onclick" });
    }
};
scwin.btn_stDisabled_onclick    = function () {
    try {
     scwin.applyState("disabled"); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_stDisabled_onclick" });
    }
};
scwin.btn_stEnabled_onclick     = function () {
    try {
     scwin.applyState("enabled"); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_stEnabled_onclick" });
    }
};
scwin.btn_stError_onclick       = function () {
    try {
     scwin.applyState("error"); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_stError_onclick" });
    }
};
scwin.btn_stInsertReady_onclick = function () {
    try {
     scwin.applyState("insertReady"); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_stInsertReady_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_stOverride_onclick
 * @description override 시연 — update 상태지만 이 화면에서는 [삭제] 를 항상 비활성으로 예외 처리.
 * @hidden N
*/
scwin.btn_stOverride_onclick = function () {
    try {
        scwin.applyState("update", { override: { "delete": false } });
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_stOverride_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_stPrintReady_onclick
 * @description registerButtonState 로 등록한 화면 전용 상태(printReady) 적용 시연.
 * @hidden N
*/
scwin.btn_stPrintReady_onclick = function () {
    try {
        scwin.applyState("printReady");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_stPrintReady_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_stAdhoc_onclick
 * @description 즉석 상태 객체 시연 — 등록 없이 1회성 정책({ enable: ["print"] }) 적용.
 * @hidden N
*/
scwin.btn_stAdhoc_onclick = function () {
    try {
        scwin.applyState({ enable: ["print"] });
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_stAdhoc_onclick" });
    }
};

// ── 대상 버튼 (활성 상태 확인용 — 클릭 시 동작 알림) ──
scwin.btn_add_onclick     = function () {
    try {
     $c.win.alert("[신규] 동작을 실행합니다."); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_add_onclick" });
    }
};
scwin.btnSv01_onclick     = function () {
    try {
     $c.win.alert("[저장] 동작을 실행합니다."); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btnSv01_onclick" });
    }
};
scwin.btn_edit_onclick    = function () {
    try {
     $c.win.alert("[수정] 동작을 실행합니다."); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_edit_onclick" });
    }
};
scwin.btnRemove_onclick   = function () {
    try {
     $c.win.alert("[삭제] 동작을 실행합니다."); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btnRemove_onclick" });
    }
};
scwin.btn_notice2_onclick = function () {
    try {
     $c.win.alert("[안내문] 동작을 실행합니다."); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_notice2_onclick" });
    }
};
scwin.btnGian_onclick     = function () {
    try {
     $c.win.alert("[기안] 동작을 실행합니다."); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btnGian_onclick" });
    }
};
scwin.btn_prt_onclick     = function () {
    try {
     $c.win.alert("[출력] 동작을 실행합니다."); 
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPBTN10000.btn_prt_onclick" });
    }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.applyState
 * @author Inswave
 * @date 2026. 08. 26
 * @description 버튼 그룹에 상태를 적용하고 현재 상태를 화면에 표시한다.
 * @param {String|Object} status 상태명 또는 즉석 상태 객체
 * @param {Object} opt (선택) setButtonState 옵션 ({ override: ... })
 * @hidden N
*/
scwin.applyState = function (status, opt) {
    $c.util.setButtonState("grp_btnBox", status, scwin.BTN_MAP, opt);

    const label = (typeof status === "string") ? status : "즉석 " + JSON.stringify(status);
    spn_status.setValue("현재 상태 : " + label + ((opt && opt.override) ? " (+override " + JSON.stringify(opt.override) + ")" : ""));
};
